/**
 * Evalúa una fórmula dada en función del estado actual del spreadsheet (estado).
 * @param {string} formula - La cadena de texto que podría ser una fórmula (ej: "=SUMA(A1:A3)").
 * @returns {string} El resultado calculado como string, o la fórmula original si no se pudo calcular.
 */
function calculateValue(formula) {
    if (!formula || !formula.startsWith('=')) return formula;

    let expression = formula.substring(1).trim(); // Eliminar el '=' inicial

    // -----------------------------
    // 1. Manejo de SUMA (SUMA(rango) o SUMA(célula, celda...))
    // -----------------------------
    const sumMatch = expression.match(/^SUMA\((.*)\)$/i);
    if (sumMatch) {
        const content = sumMatch[1]; // Contenido dentro de los paréntesis
        let totalSum = 0;

        // Dividir por argumentos separados por coma
        const argumentsList = content.split(',');

        for (const arg of argumentsList) {
            let trimmedArg = arg.trim();
            if (!trimmedArg) continue;

            if (trimmedArg.includes(':')) {
                // Caso de RANGO: A1:A3
                const rangeParts = trimmedArg.split(':');
                if (rangeParts.length !== 2) continue;

                let startId = rangeParts[0].toUpperCase();
                let endId = rangeParts[1].toUpperCase();

                // Asumimos que el rango es vertical (mismo encabezado de columna, diferentes números de fila)
                const col = startId[0]; 
                const startRow = Math.min(parseInt(startId.substring(1)), parseInt(endId.substring(1)));
                const endRow = Math.max(parseInt(startId.substring(1)), parseInt(endId.substring(1)));

                let currentTotal = 0;
                for (let r = startRow; r <= endRow; r++) {
                    const cellId = `${col}${r}`; 
                    currentTotal += getNumericValue(cellId);
                }
                totalSum += currentTotal;

            } else {
                // Caso de CÉLULA SUELTA: A1 o B3
                let singleCellId = trimmedArg.toUpperCase();
                if (estado[singleCellId] !== undefined) {
                     totalSum += getNumericValue(singleCellId);
                }
            }
        }
        return totalSum.toString(); // Devolver el resultado como string para que render() lo muestre
    }

    // -----------------------------
    // 2. Manejo de Operaciones Aritméticas: =A1-B1, etc.
    // -----------------------------
    try {
        // Reemplazar todas las referencias a celdas (ej: A1) con sus valores numéricos reales
        let evaluatedExpression = expression.replace(/([A-Z]+[0-9]+)/g, (match) => {
            const value = getNumericValue(match);
            return value; // Sustituir la referencia por su valor numérico
        });

        // Evaluar la expresión resultante de forma segura usando new Function()
        const result = new Function('return ' + evaluatedExpression)();

        // Si el resultado es un número, lo convertimos a string.
        return String(result); 
    } catch (e) {
        console.error("Error evaluando fórmula:", e);
        return formula; // Devolver la fórmula original si falla la evaluación
    }
}
