 * @param {string} formula - La fórmula a evaluar, debe empezar con '='.
 * @returns {number|null} El resultado numérico calculado o null si falla la evaluación.
 */
function calculateFormula(formula) {
    if (!formula || !formula.startsWith('=')) {
        return null; // No es una fórmula
    }

    // 1. Simplificación: Convertir nombres de funciones a JS (SUMA -> Math.sum) y asegurar el formato de la fórmula para evaluación matemática simple.
    let simplifiedFormula = formula.toUpperCase();
    simplifiedFormula = simplifiedFormula.replace(/SUMA\(([^)]+)\)/g, (match, content) => {
        // Maneja rangos o listados dentro de SUMA(A1:B2) o SUMA(A1;B2)
        const cellReferences = content.split(/[A-Z]\d+/).filter((_, index, arr) => index === 0 || !isNaN(parseInt(arr[index].match(/\d+/) || '')));
        if (cellReferences.length === 0) return '0';

        let sumValue = 0;
        const uniqueRefs = new Set(content.split(/[,;\s]+/).map(ref => ref.trim()).filter(Boolean));

        for (const cellRef of uniqueRefs) {
            // Simplificación: Solo necesitamos extraer la referencia de celda A1, B2, etc.
            const match = cellRef.match(/[A-Z]+\d+/);
            if (match) {
                const cellId = match[0];
                sumValue += getCellValue(cellId);
            }
        }
        return `(${sumValue})`; // Devolvemos el resultado como una cadena numérica para que Math.eval lo use, aunque esto es complejo. Simplificamos usando un eval robusto después.

    });


    // 2. Evaluación de la fórmula (Este paso requiere manejo avanzado de expresiones matemáticas y referencias de celda).
    // Dado que estamos limitados a Vanilla JS sin librerías de parsing, utilizaremos una aproximación basada en reemplazo de referencias por valores numéricos.

    let expression = simplifiedFormula;

    // Paso 2a: Reemplazar todas las referencias de celda (ej: A1) con su valor numérico actual.
    const cellRegex = /([A-Z]+\d+)/g;
    expression = expression.replace(cellRegex, (match) => {
        return getCellValue(match); // Esto reemplaza "A1" por el número en estado["A1"]
    });

    // Paso 2b: Evaluar la expresión matemática resultante.
    try {
        // Math.eval es peligroso pero necesario para este contexto de prueba sin librerías de parsing.
        const result = Function(`return ${expression}`)();
        return parseFloat(result);
    } catch (e) {
        console.error("Error al evaluar la fórmula:", e, "Fórmula original:", formula);
        return null; // Fallo en el cálculo
    }
}
