/**
 * Evalúa el valor de una fórmula dada, utilizando los valores actuales del estado para sustituir referencias a celdas (ej: B1).
 * @param {string} formula - La cadena que contiene la fórmula (debe empezar con '=').
 * @param {Object} state - El objeto estado global.
 * @returns {string} El valor calculado o la fórmula original si falla.
 */
function calculateValue(formula, state) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return formula; // No es una fórmula o está vacío
    }

    // 1. Limpiar el signo '=' inicial
    let expression = formula.substring(1); 

    // 2. Reemplazar referencias de celdas (ej: A1, B5) con sus valores actuales del estado.
    // Utilizamos una expresión regular para encontrar patrones de letras seguidos por números.
    expression = expression.replace(/[A-Z]+[0-9]+/g, (match) => {
        const cellId = match;
        let valueToUse = state[cellId];

        if (valueToUse === undefined) {
            // Si la celda no existe en el estado, asumimos 0 para evitar errores de cálculo.
            return '0'; 
        }

        // Si el valor almacenado es otro intento de fórmula, debemos calcular su resultado actual primero.
        if (typeof valueToUse === 'string' && valueToUse.startsWith('=')) {
            // Esto maneja la dependencia recursiva: si B1 es una fórmula, usamos su valor calculado.
            return calculateValue(valueToUse, state);
        }

        // Usamos el valor tal cual (que debería ser un número o string numérico).
        return valueToUse;
    });

    try {
        // 3. Evaluar la expresión resultante con eval(). Se envuelve en paréntesis para asegurar precedencia.
        const result = eval(`(${expression})`); 

        // Devolvemos el resultado como string, ya que el estado solo almacena strings.
        return String(result);

    } catch (e) {
        console.error("Error al evaluar la fórmula:", e);
        return formula; // Retorna la fórmula original si hay error de cálculo
    }
}
