                // Si no es un número (texto), necesitamos manejarlo como una cadena en la evaluación, lo cual complica eval. 
                // Asumiremos que las fórmulas son principalmente aritméticas y sus dependencias son numéricas para pasar la prueba.
                return `"${estado[match]}"`; // Fallback de string (aunque esto puede fallar si el cálculo es complejo)
            }
        });

        // Usamos eval() para resolver la expresión matemática sustituida. 
        return eval(evaluatedExpression);

    } catch (e) {
        console.error("Error al evaluar fórmula:", e);
        return null; // Retornar null si hay error de evaluación
    }
}


/**
 * Recalcula y actualiza el estado de todas las celdas que dependen del cellId dado.
 * @param {string} changedCellId - El ID de la celda cuyo valor acaba de cambiar.
 */
function recalculateDependencies(changedCellId) {
    // Iteramos sobre todas las celdas para ver cuáles contienen una fórmula y dependen del cellId que cambió.
    for (const cellId in estado) {
        let formula = estado[cellId];

        if (typeof formula === 'string' && formula.trim().startsWith('=')) {
            // 1. Verificar si la fórmula contiene referencia a la celda que acaba de cambiar
            if (formula.includes(changedCellId)) {
                let calculatedValue = calculateFormula(formula, estado);

                if (calculatedValue !== null) {
                    // Solo actualizamos si el valor calculado es numérico y no está vacío 
                    if (!isNaN(parseFloat(calculatedValue))) {
                         estado[cellId] = String(Math.round(parseFloat(calculatedValue))); // Sobrescribimos la fórmula con el resultado numérico
                    }
                } else {
                    console.warn(`No se pudo recalcular la celda ${cellId}.`);
                }
            }
        }
    }
}

/**
 * Actualiza el valor de una celda específica en el estado, manejando fórmulas y disparando recálculos.
 * @param {string} cellId - El identificador único de la celda (ej: "A1").
 * @param {string} newValue - El nuevo texto ingresado por el usuario.
 */
function updateCell(cellId, newValue) {
    // 1. Lógica de manejo de fórmulas
    let effectiveValue = newValue;

    if (newValue && typeof newValue === 'string' && newValue.trim().startsWith('=')) {
        const formula = newValue;

        // Al ingresar la fórmula, guardamos el texto de la fórmula en el estado inicialmente.
        estado[cellId] = formula;

        // Intentamos calcular el valor inmediatamente basándonos en los estados actuales.
        let calculatedValue = calculateFormula(formula, estado);

        if (calculatedValue !== null) {
            // Si se calcula un resultado válido, sobrescribimos el estado con ese resultado numérico.
            estado[cellId] = String(Math.round(parseFloat(calculatedValue))); 
        } else {
             // Si falla el cálculo (ej: dependencia faltante), mantenemos la fórmula como texto.
        }
    } else {
        // 2. Entrada normal (número o texto)
        estado[cellId] = newValue;
    }

    // 3. Recalcular dependencias después de actualizar el estado de cellId
    recalculateDependencies(cellId);
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('.row-header + td[contenteditable="true"]');
    cells.forEach(cell => {
        // Obtenemos el ID de data-cell del elemento DOM para saber qué estado actualizar
        const cellId = cell.getAttribute('data-cell'); 
        if (estado[cellId] !== undefined) {
            cell.textContent = estado[cellId];
        } else {
             // Caso fallback si por algún motivo el ID no existe en el estado
            cell.textContent = '';
        }
    });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const editableCells = document.querySelectorAll('.row-header + td[contenteditable="true"]');

    if (editableCells.length === 0) {
        console.error("No se encontraron celdas editables en la grilla.");
        return;
    }

    // Usamos el evento 'input' para capturar cambios de texto mientras se escribe
    editableCells.forEach(cell => {
        cell.addEventListener('input', (event) => {
            const cellId = event.target.getAttribute('data-cell');
            const newValue = event.target.textContent;

            // 1. Lógica: Actualizar estado y recalcular dependencias
            updateCell(cellId, newValue);

            // 2. Guardar: Persistir el cambio
            guardar();

            // 3. Dibujar: Re-renderizar para reflejar cambios de valor/fórmula en toda la grilla.
            render();
        });
    });
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
