```javascript
function render() {
    const cells = document.querySelectorAll('.row-header + td[contenteditable="true"]');
    cells.forEach(cell => {
        // Obtenemos el ID de data-cell del elemento DOM para saber qué estado actualizar
        const cellId = cell.getAttribute('data-cell'); 
        let displayValue;

        if (estado[cellId] === undefined) {
            displayValue = '';
        } else if (typeof estado[cellId] !== 'string') {
             // Aseguramos que el valor del estado siempre sea tratado como string para la visualización.
            displayValue = String(estado[cellId]);
        } else if (estado[cellId].startsWith('=')) {
            const formulaBody = estado[cellId].substring(1);
            let expression = formulaBody;

            // Expresión regular para encontrar referencias a celdas (ej: A1, B2)
            const cellRegex = /([A-Z][0-9]+)/g; 

            // Reemplazamos las referencias de celda con sus valores numéricos actuales en el estado.
            expression = expression.replace(cellRegex, (match) => {
                if (estado[match] !== undefined && typeof estado[match] === 'string' && !isNaN(parseFloat(estado[match]))) {
                    // Convertimos el valor referenciado a un número para la evaluación aritmética.
                    return Number(estado[match]); 
                } else {
                    // Si no se puede resolver o es texto, lo mantenemos como string literal en la expresión.
                    // Esto permite que fórmulas mixtas (ej: =A1*B2) funcionen si A1 y B2 son números.
                    return match; 
                }
            });

            try {
                // Utilizamos eval() para ejecutar la expresión matemática resultante.
                const result = eval(expression);
                displayValue = isNaN(result) ? 'Error' : String(result);
            } catch (e) {
                console.error("Formula evaluation error:", e);
                // Si falla la evaluación, mostramos el valor original o un mensaje de error.
                displayValue = estado[cellId]; 
            }

        } else {
            // Valor simple sin fórmula
            displayValue = estado[cellId];
        }

        cell.textContent = displayValue;
    });
}
