```javascript
function showContextMenu(e, cellId) {
    // 1. Limpiar cualquier menú existente
    const existingMenu = document.getElementById('color-context-menu');
    if (existingMenu) {
        existingMenu.remove();
    }

    // 2. Crear y posicionar el menú
    const menu = document.createElement('div');
    menu.id = 'color-context-menu';
    menu.className = 'context-menu';
    const cellsContainer = document.getElementById('spreadsheet-grid');
    cellsContainer.appendChild(menu);

    // 3. Agregar opciones de color (pueden ser colores fijos o dinámicos)
    const colors = [
        { name: "Rojo", hex: "#FF0000" },
        { name: "Azul", hex: "#0000FF" },
        { name: "Verde", hex: "#00AA00" }
    ];

    colors.forEach(color => {
        const colorButton = document.createElement('button');
        colorButton.className = 'context-menu-item';
        colorButton.style.backgroundColor = color.hex;
        colorButton.textContent = color.name;
        colorButton.addEventListener('click', () => {
            // 4. Aplicar el color y limpiar menú
            setColor(cellId, color.hex);
            menu.remove(); // Remover menú después de la acción
        });
        menu.appendChild(colorButton);
    });

    // 5. Posicionar el menú en la posición del click (e.clientX/Y)
    menu.style.top = `${e.clientY - menu.offsetHeight / 2}px`;
    menu.style.left = `${e.clientX}px`;
}
