function conectar() {
    const editableCells = document.querySelectorAll('.row-header + td[contenteditable="true"]');

    if (editableCells.length === 0) {
        console.error("No se encontraron celdas editables en la grilla.");
        return;
    }

    // --- 1. Listener de Input para texto ---
    editableCells.forEach(cell => {
        cell.addEventListener('input', (event) => {
            const cellId = event.target.getAttribute('data-cell');
            const newValue = event.target.textContent;

            // 1. Lógica: Actualizar estado del valor
            updateCell(cellId, newValue);

            // 2. Guardar y Dibujar
            guardar();
            render();
        });
    });

    // --- 2. Listener de Clic Derecho (Context Menu) en las celdas ---
    document.getElementById('spreadsheet-grid').addEventListener('contextmenu', function(e) {
        const targetCell = e.target.closest('td[contenteditable="true"]');
        if (targetCell) {
            const cellId = targetCell.getAttribute('data-cell');
            // Mostrar el menú de contexto personalizado en lugar del nativo
            showContextMenu(e, cellId); 
        } else {
            // Si se hace clic derecho fuera de una celda de datos editable, evitar cualquier acción especial
            return true; 
        }
    });

    // --- 3. Listener para el control de color global (UI) ---
    document.getElementById('applyColorButton').addEventListener('click', () => {
        const colorPicker = document.getElementById('colorPicker');
        let targetCellId = null;

        // Determinar qué celda está activa/seleccionada en este momento. 
        // Intentamos usar la última celda con foco, o si no hay foco, ignorar la acción (aunque esto podría ser mejor manejado por un sistema de selección).
        const activeElement = document.activeElement;

        if (activeElement && activeElement.hasAttribute('data-cell')) {
            targetCellId = activeElement.getAttribute('data-cell');
        } else {
            alert("Por favor, haga clic en una celda de la hoja antes de aplicar el color.");
            return;
        }

        if (targetCellId) {
            const selectedColor = colorPicker.value;
            handleColorApplication(targetCellId, selectedColor);
        }
    });

    // --- 4. Listener para el cambio del input color global (UI) ---
    document.getElementById('colorPicker').addEventListener('input', () => {
        // Esto solo actualiza la vista del picker, no necesita acción inmediata en la grilla.
    });
}
