### script.js
```javascript
// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const editableCells = document.querySelectorAll('.row-header + td[contenteditable="true"]');

    if (editableCells.length === 0) {
        console.error("No se encontraron celdas editables en la grilla.");
        return;
    }

    // Usamos el evento 'input' para capturar cambios de texto mientras se escribe
    editableCells.forEach(cell => {
        cell.addEventListener('input', (event) => {
            const cellId = event.target.getAttribute('data-cell');
            const newValue = event.target.textContent;

            // 1. Lógica: Actualizar estado
            updateCell(cellId, newValue);

            // 2. Guardar: Persistir el cambio
            guardar();

            // 3. Dibujar: Re-renderizar (aunque en este caso solo se actualiza la celda que disparó el evento)
            // Llamamos a render() para asegurar coherencia con el patrón de diseño.
            render();
        });
    });

    // Configuración de controles de columna (las letras A, B, C...)
    const columnHeaders = document.querySelectorAll('.col-header');
    columnHeaders.forEach(header => {
        header.addEventListener('click', (event) => {
            // Asumimos que el contenido del header es la letra de la columna
            const colLetter = event.currentTarget.textContent.trim().toUpperCase(); 

            if (!colLetter || !/[A-Z]/.test(colLetter)) return;

            // Borrar todo el contenido de la columna seleccionada (R1 a R20)
            for (let r = 1; r <= 20; r++) {
                const cellId = `${colLetter}${r}`;
                updateCell(cellId, ''); // Establece el estado vacío para cada celda en esta columna
            }

            // Guardar y redibujar la grilla completa
            guardar();
            render();
        });
    });
}
```

