function selectColumn(columnLetter) {
    // 1. Limpiar selección anterior
    document.querySelectorAll('.col-header').forEach(th => {
        th.classList.remove('selected-column');
        th.style.cursor = 'default';
    });

    // 2. Aplicar nueva selección
    const selectedHeader = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected-column');
        selectedHeader.style.cursor = 'pointer'; // Mantener el cursor interactivo
        estado.selectedColumn = columnLetter;
        console.log(`Columna ${columnLetter} seleccionada.`);
