### FUNCION: clearSelectedColumnData
```js
function clearSelectedColumnData() {
    const col = estado.selectedColumn;
    if (!col) {
        alert("Por favor, selecciona una columna primero.");
        return false;
    }

    let cellsToClear = [];
    let stateChanged = false;

    // 1. Limpiar el estado (datos) para todas las celdas de esa columna
    for (let r = 1; r <= 20; r++) {
        const cellId = `${col}${r}`;
        if (estado[cellId] !== undefined && estado[cellId] !== '') {
            estado[cellId] = '';
            cellsToClear.push(document.querySelector(`[data-cell="${cellId}"]`));
            stateChanged = true;
        } else if (estado[cellId] === '' && document.querySelector(`[data-cell="${cellId}"]`) && document.querySelector(`[data-cell="${cellId}"]`).textContent !== '') {
             // Asegurar que el DOM se vacía si por alguna razón no está en estado pero tiene contenido
            cellsToClear.push(document.querySelector(`[data-cell="${cellId}"]`));
        }
    }

    if (stateChanged || cellsToClear.length > 0) {
        // 2. Actualizar el DOM de las celdas vacías
        cellsToClear.forEach(cell => cell.textContent = '');

        // 3. Guardar y renderizar para reflejar los cambios
        guardar();
        render();
        return true;
    } else {
        alert("No hay contenido que borrar en esta columna.");
        return false;
    }
}
