### FUNCION: deleteSelectedColumn
```js
function deleteSelectedColumn() {
    const col = estado.selectedColumn;
    if (!col) {
        alert("Por favor, selecciona una columna primero.");
        return false;
    }

    // 1. Eliminar el encabezado de la columna (thead)
    const headerCell = document.querySelector(`.col-header[data-column="${col}"]`);
    if (headerCell) {
        headerCell.remove();
    } else {
        console.warn(`No se encontró el encabezado de la columna ${col}.`);
        return false;
    }

    // 2. Eliminar todas las celdas de datos correspondientes (tbody)
    const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    let cellsRemovedCount = 0;

    rows.forEach(row => {
        const cellToRemove = row.querySelector(`[data-cell^="${col}"]`);
        if (cellToRemove) {
            cellToRemove.remove();
            cellsRemovedCount++;
        }
    });

    // 3. Actualizar el estado, eliminando todas las claves de esa columna
    let stateKeysCleared = 0;
    for (let r = 1; r <= 20; r++) {
        const cellId = `${col}${r}`;
        if (estado[cellId] !== undefined) {
            delete estado[cellId];
            stateKeysCleared++;
        }
    }

    // 4. Guardar y renderizar
    guardar();
    render(); 
    alert(`Columna ${col} eliminada exitosamente. (${cellsRemovedCount} celdas vacías, ${stateKeysCleared} datos de estado removidos)`);
    return true;
}
