### FUNCION: selectColumn
```javascript
/**
 * Selecciona una columna dada su letra, actualizando el estado y la UI.
 * @param {string} columnLetter - La letra de la columna (ej: "A").
 */
function selectColumn(columnLetter) {
    selectedColumnLetter = columnLetter;

    // 1. Limpiar selección anterior en todo el contenedor
    document.querySelectorAll('.col-header, .spreadsheet-grid td').forEach(el => {
        el.classList.remove('selected-column');
    });

    // 2. Marcar la columna seleccionada (Header)
    const headerElement = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (headerElement) {
        headerElement.classList.add('selected-column');
    }

    // 3. Marcar todas las celdas de la columna seleccionada en el grid
    for (let r = 1; r <= 20; r++) {
        const cellId = `${columnLetter}${r}`;
        const cellElement = document.querySelector(`.spreadsheet-grid [data-cell="${cellId}"]`);
        if (cellElement) {
            cellElement.classList.add('selected-column');
        }
    }

    console.log(`Columna ${columnLetter} seleccionada.`);
}
