### FUNCION: conectar
```javascript
function conectar() {
    const editableCells = document.querySelectorAll('.row-header + td[contenteditable="true"]');

    if (editableCells.length === 0) {
        console.error("No se encontraron celdas editables en la grilla.");
        return;
    }

    // Event listener para la edición de celdas (Input)
    editableCells.forEach(cell => {
        cell.addEventListener('input', (event) => {
            const cellId = event.target.getAttribute('data-cell');
            const newValue = event.target.textContent;

            // 1. Lógica: Actualizar estado
            updateCell(cellId, newValue);

            // 2. Guardar: Persistir el cambio
            guardar();

            // 3. Dibujar: Re-renderizar (aunque en este caso solo se actualiza la celda que disparó el evento)
            render();
        });
    });


    // ==============================================
    // NUEVO: Manejo de eventos para selección de columnas
    // Buscamos los elementos con clase col-header que representan las letras A, B, C...
    const columnHeaders = document.querySelectorAll('.col-header');

    columnHeaders.forEach(header => {
        // Asumimos que el header tiene un atributo data-column con la letra (A, B, etc.)
        if (header.hasAttribute('data-column')) {
            header.addEventListener('click', () => {
                const columnLetter = header.getAttribute('data-column');
                selectColumn(columnLetter);
            });
        }
    });

    // Event Listeners para los nuevos controles de columna:
    document.getElementById('btn-clear-data').addEventListener('click', clearSelectedColumnData);
    document.getElementById('btn-change-color').addEventListener('click', setBackgroundColorForColumn);
    document.getElementById('btn-delete-column').addEventListener('click', deleteSelectedColumn);

}
```

