function selectColumn(columnId) {
    // 1. Limpiar selección previa y controles
    const controls = document.getElementById('column-controls');
    if (controls) controls.innerHTML = '';
    document.querySelectorAll('.col-header').forEach(th => th.classList.remove('selected'));

    // 2. Actualizar estado de selección
    estado.selectedColumn = columnId;

    // 3. Marcar el encabezado como seleccionado y mostrar controles
    const selectedHeader = document.querySelector(`.col-header[data-column="${columnId}"]`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected');
    }

    // 4. Generar controles de acción
    controls.innerHTML = `
        <div class="action-buttons">
            <button id="clear-col-btn" data-action="clear">Borrar Contenido Columna</button>
            <button id="color-col-btn" data-action="color">Cambiar Fondo Color</button>
            <input type="color" id="color-picker" value="#ff0000">
            <button id="delete-col-btn" data-action="delete">Borrar Columna</button>
        </div>
    `;

    // 5. Conectar los nuevos eventos de control
    document.getElementById('clear-col-btn').onclick = () => {
        const columnId = estado.selectedColumn;
        if (columnId) clearColumnContents(columnId);
    };

    document.getElementById('delete-col-btn').onclick = () => {
        const columnId = estado.selectedColumn;
        if (window.confirm(`¿Está seguro de que desea borrar la columna ${columnId}? Esto no se puede deshacer.`)) {
            deleteColumn(columnId);
        }
    };

    document.getElementById('color-col-btn').onclick = () => {
        const columnId = estado.selectedColumn;
        if (window.confirm("Ingrese el color de fondo para todas las celdas de esta columna.")) {
            const color = document.getElementById('color-picker').value;
            setBackgroundColor(columnId, color);
        }
    };
}
