```js
/**
 * Elimina una columna completa (datos y estructura).
 * Nota: Esta implementación solo elimina los datos del estado y requiere un re-render complejo para el DOM,
 * por lo que se centra en la lógica de datos. La eliminación estructural total es muy compleja sin modificar el HTML/CSS base.
 * @param {string} columnLetter - La letra de la columna a eliminar (ej: "C").
 */
function deleteColumn(columnLetter) {
    if (!estado['selectedColumn'] || estado['selectedColumn'] !== columnLetter) {
        console.warn("Debe seleccionar una columna antes de intentar borrarla.");
        return;
    }

    // 1. Eliminar todos los datos asociados a esa columna en el estado
    const keysToDelete = [];
    for (let r = 1; r <= 20; r++) {
        const cellId = `${columnLetter}${r}`;
        if (estado[cellId] !== undefined) {
            keysToDelete.push(cellId);
        }
