let estado = {};
const CLAVE = "app";

/**
 * Inicializa el objeto estado con todas las celdas posibles (A1 a J20) vacías.
 */
function initializeEstado() {
    estado = {};
    // Generamos combinaciones de columnas A-J y filas 1-20
    const columns = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    for (let r = 1; r <= 20; r++) {
        for (let cIndex = 0; cIndex < columns.length; cIndex++) {
            const column = columns[cIndex];
            const cellId = `${column}${r}`;
            estado[cellId] = ''; // Inicializa cada celda con un valor vacío
        }
    }
}

function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
             // Si hay datos guardados, los cargamos y los fusionamos sobre el estado inicializado
            const loadedState = JSON.parse(s);
            Object.keys(estado).forEach(key => {
                if (loadedState[key] !== undefined) {
                    estado[key] = loadedState[key];
                }
            });
        } else {
             // Si no hay datos, aseguramos que el estado esté inicializado correctamente
             initializeEstado();
        }
    } catch (e) { 
        console.error("Error al cargar el estado:", e); 
        initializeEstado(); // Fallback si localStorage falla
    } 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) { 
        console.error("Error al guardar el estado:", e); 
    } 
}

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Actualiza el valor de una celda específica en el estado.
 * @param {string} cellId - El identificador único de la celda (ej: "A1").
 * @param {string} newValue - El nuevo texto ingresado por el usuario.
 */
function updateCell(cellId, newValue) {
    if (estado[cellId] !== undefined) {
        estado[cellId] = newValue;
    } else {
        console.warn(`Celda ${cellId} no encontrada en el estado.`);
    }
}

/**
 * Selecciona una columna por su letra y actualiza el estado visual y lógico.
 * @param {string} columnLetter - La letra de la columna seleccionada (ej: "A").
 */
function selectColumn(columnLetter) {
    // 1. Actualizar estado interno (opcional, pero ayuda a saber qué está seleccionado)
    estado['selectedColumn'] = columnLetter;

    // 2. Limpiar selección visual previa en todos los encabezados
    document.querySelectorAll('.col-header').forEach(th => {
        th.classList.remove('selected');
    });

    // 3. Aplicar selección visual al encabezado actual
    const selectedHeader = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected');
    }

    // Habilitar controles de columna
    document.getElementById('btn-clear-col').disabled = false;
    document.getElementById('btn-delete-col').disabled = false;
    document.getElementById('btn-set-color-col').disabled = false;
    document.getElementById('color-picker').value = '#ff0000'; // Resetear color por defecto
}

/**
 * Elimina una columna completa (datos y estructura).
 * @param {string} columnLetter - La letra de la columna a eliminar (ej: "C").
 */
function deleteColumn(columnLetter) {
    if (!estado['selectedColumn'] || estado['selectedColumn'] !== columnLetter) {
        console.warn("Debe seleccionar una columna antes de intentar borrarla.");
        return;
    }

    // 1. Eliminar todos los datos asociados a esa columna en el estado
    const keysToDelete = [];
    for (let r = 1; r <= 20; r++) {
        const cellId = `${columnLetter}${r}`;
        if (estado[cellId] !== undefined) {
            keysToDelete.push(cellId);
        }
    }

    keysToDelete.forEach(key => delete estado[key]);
    console.log(`Datos de la columna ${columnLetter} borrados del estado.`);
}

/**
 * Cambia el color de fondo de todas las celdas en la columna seleccionada.
 * @param {string} columnLetter - La letra de la columna a colorear (ej: "A").
 * @param {string} color - El código hexadecimal del color (#RRGGBB).
 */
function setColorForColumn(columnLetter, color) {
    if (!estado['selectedColumn'] || estado['selectedColumn'] !== columnLetter) {
        console.warn("Debe seleccionar una columna antes de intentar cambiarle el color.");
        return;
    }

    // 1. Actualizar visualmente todas las celdas en la columna seleccionada
    const cells = document.querySelectorAll(`.col-header + td[data-cell^="${columnLetter}"]`);
    cells.forEach(cell => {
        cell.style.backgroundColor = color;
    });

    // 2. Actualizar estado (si fuera necesario guardar el color, pero lo dejamos solo visual para este scope)
}

/**
 * Borra el contenido de todas las celdas en la columna seleccionada y actualiza el estado.
 */
function clearColumnContent(columnLetter) {
    if (!estado['selectedColumn'] || estado['selectedColumn'] !== columnLetter) {
        console.warn("Debe seleccionar una columna antes de intentar borrar su contenido.");
        return;
    }

    // 1. Borrar el contenido del DOM y actualizar el estado para todas las celdas
    const cells = document.querySelectorAll(`.col-header + td[data-cell^="${columnLetter}"]`);
    cells.forEach(cell => {
        cell.textContent = ''; // Limpiar visualmente
    });

    // 2. Actualizar la fuente de verdad (estado)
    for (let r = 1; r <= 20; r++) {
        const cellId = `${columnLetter}${r}`;
        if (estado[cellId] !== undefined) {
            estado[cellId] = ''; // Limpiar el valor en el estado
        }
    }

    // 3. Guardar y renderizar para asegurar la coherencia
    guardar();
    render();
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('.row-header + td[contenteditable="true"]');
    cells.forEach(cell => {
        // Obtenemos el ID de data-cell del elemento DOM para saber qué estado actualizar
        const cellId = cell.getAttribute('data-cell'); 
        if (estado[cellId] !== undefined) {
            cell.textContent = estado[cellId];
        } else {
             // Caso fallback si por algún motivo el ID no existe en el estado
            cell.textContent = '';
        }
    });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const editableCells = document.querySelectorAll('.row-header + td[contenteditable="true"]');
    const columnHeaders = document.querySelectorAll('.col-header');

    // 1. Evento para seleccionar columna (Clic en la letra)
    columnHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const columnLetter = this.getAttribute('data-column');
            selectColumn(columnLetter);
        });
    });

    // 2. Eventos de los nuevos controles de columna (Delegación)
    document.getElementById('btn-clear-col').addEventListener('click', function() {
        const selectedCol = estado['selectedColumn'];
        if (selectedCol) {
            clearColumnContent(selectedCol);
        }
    });

    document.getElementById('btn-delete-col').addEventListener('click', function() {
        const selectedCol = estado['selectedColumn'];
        if (selectedCol) {
            // Advertencia: En un entorno real, se debería pedir confirmación al usuario aquí.
            deleteColumn(selectedCol);
        }
    });

    document.getElementById('btn-set-color-col').addEventListener('click', function() {
        const selectedCol = estado['selectedColumn'];
        const color = document.getElementById('color-picker').value;
        if (selectedCol) {
            setColorForColumn(selectedCol, color);
        }
    });


    // 3. Evento de entrada en celdas editables (EXISTENTE)
    editableCells.forEach(cell => {
        cell.addEventListener('input', (event) => {
            const cellId = event.target.getAttribute('data-cell');
            const newValue = event.target.textContent;

            // 1. Lógica: Actualizar estado
            updateCell(cellId, newValue);

            // 2. Guardar: Persistir el cambio
            guardar();

            // 3. Dibujar: Re-renderizar (aunque en este caso solo se actualiza la celda que disparó el evento)
            render();
        });
    });
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
