### FUNCION: deleteSelectedRow
```js
function deleteSelectedRow() {
    const selectedRowElement = document.querySelector('.selected-row');
    if (!selectedRowElement || !selectedRowElement.closest('tr')) return;

    // 1. Obtener el índice de la fila (data-row en el header)
    const rowHeader = selectedRowElement.querySelector('.row-header');
    if (!rowHeader) return;
    const rowNumber = parseInt(rowHeader.getAttribute('data-row'));

    // 2. Identificar todas las celdas de la fila (A, B, C... J)
    let cellsToDelete = [];
    for (let columnLetterCode = 'A'.charCodeAt(0); columnLetterCode <= 'J'.charCodeAt(0); columnLetterCode++) {
        const columnLetter = String.fromCharCode(columnLetterCode);
        const cellId = `${columnLetter}${rowNumber}`;
        cellsToDelete.push({ id: cellId, element: selectedRowElement.querySelector(`[data-cell="${cellId}"]`) });
    }

    // 3. Actualizar el estado borrando los datos de la fila
    for (const { id } of cellsToDelete) {
        delete estado[id];
    }

    // 4. Eliminar la fila del DOM
    selectedRowElement.closest('tr').remove();

    // 5. Guardar y redibujar el resto de la grilla
    guardar();
    render();
}
