function deleteSelectedRow() {
    const selectedRowId = estado.selectedRow;
    if (!selectedRowId) {
        alert("Por favor, selecciona una fila para borrar.");
        return false;
    }

    if (!confirm(`¿Estás seguro de que quieres borrar la Fila ${selectedRowId}? Esta acción no se puede deshacer.`)) {
        return false;
    }

    // 1. Lógica: Eliminar el estado de esta fila (A-J)
    const rowCells = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    for (let c = 0; c < rowCells.length; c++) {
        const columnLetter = rowCells[c];
        const cellId = `${columnLetter}${selectedRowId}`;
        delete estado[cellId];
    }

    // 2. Dibujo: Eliminar la fila del DOM
    const rowElement = document.querySelector(`.row-header[data-row="${selectedRowId}"]`).closest('tr');
    if (rowElement) {
        rowElement.remove();
    }

    // 3. Actualizar estado global y persistir
    estado.selectedRow = null;
    guardar();
    render(); // Re-renderiza para limpiar la selección visual
    return true;
}
